#include <vector>
#include <cstddef>
#include <omp.h>

/* Compute the highest node degree in the undirected graph.
   The graph is defined by an NxN adjacency matrix A stored in row‑major order.
   Returns the maximum degree (0 for an empty graph). */
int maxDegree(const std::vector<int>& A, std::size_t N)
{
    // Guard against empty input
    if (N == 0) return 0;

    int maxDeg = 0;

    // Parallel loop over rows (nodes).  Use a reduction to combine per‑thread maxima.
    #pragma omp parallel for reduction(max:maxDeg)
    for (std::size_t i = 0; i < N; ++i) {
        int degree = 0;
        std::size_t rowStart = i * N;
        for (std::size_t j = 0; j < N; ++j) {
            degree += A[rowStart + j];
        }
        // The reduction clause will safely update maxDeg.
        if (degree > maxDeg) {
            maxDeg = degree;
        }
    }

    return maxDeg;
}
